t0 = time.perf_counter()
p = c.post("/api/options/mcp/possibilidades",
           json={"ticker": ticker, "direction": "bullish", "lote": 100,
                 "expirations": venc},
           headers=h)
dt = time.perf_counter() - t0
print(f"  HTTP {p.status_code} em {dt:.1f}s (limite do aceite: {limite:.0f}s)")
if p.status_code == 200:
    d = p.json()
