import os, sys
from fastapi.testclient import TestClient
ticker = sys.argv[1]
from app import main
c = TestClient(main.app)
# Primeira conta de um banco vazio vira admin (bootstrap aditivo), então ela
# tem `opcoes.criar_setup` — é o que a rota exige.
r = c.post("/api/auth/register", json={"email": "fase24@local.test", "password": "senhaboa123"})
r.raise_for_status()
tok = r.json()["token"]
h = {"authorization": "Bearer " + tok}
me = c.get("/api/me", headers=h)
perms = (me.json().get("user") or me.json()).get("permissions") or []
print(f"  permissões da conta de teste: {perms}")
if "opcoes.criar_setup" not in perms:
    print("  a conta não recebeu opcoes.criar_setup — a rota vai responder 403"); sys.exit(2)
descricao = (f"Quero um setup para {ticker}: avisar quando o RSI de 14 ficar "
             f"abaixo de 30 e o fechamento estiver acima da média de 200, "
             f"por dois pregões seguidos.")
r = c.post("/api/options/mcp/setups/compilar",
           json={"ticker": ticker, "descricao": descricao}, headers=h)
print(f"  HTTP {r.status_code}")
try:
    d = r.json()
except Exception:
    print("  corpo não-JSON:", r.text[:300]); sys.exit(1)
if r.status_code == 200:
    s = d.get("setup") or {}
    print(f"  status={d.get('status')} name={s.get('name')!r} "
          f"conditions={len(s.get('conditions') or [])} logic={s.get('logic')} "
          f"consecutive_days={s.get('consecutive_days')}")
    print(f"  description preservada: {s.get('description') == descricao}")
    b = d.get("backtest") or {}
    print(f"  backtest: disparos={b.get('disparos')} "
          f"por100={b.get('disparos_por_100_pregoes_avaliaveis')} "
          f"d+5={(b.get('retorno_apos_disparo') or {}).get('d+5')}")
    print("  NADA FOI GRAVADO: é dry-run, confirm=false.")
    sys.exit(0)
print("  detalhe:", str(d)[:500])
sys.exit(1)
